insert into announcement (id, title, body, published_on)
values
    ('AN-12', 'New fingerprint readers from 1 December', 'We''re replacing the card readers at the Malé office. Drop by HR this month to register your fingerprint. It takes two minutes.', '2026-11-12'),
    ('AN-11', 'Year end dinner, 17 December', 'Hulhumalé beach, 7 pm. Bring your family. Let HR know by 5 December how many are coming.', '2026-11-08'),
    ('AN-10', 'Visa renewals need 60 days', 'Immigration has been slow lately. If your visa or work permit expires in the next two months, send your documents to HR this week.', '2026-10-28');
